@Serializable
sealed interface Command {
    @Serializable @SerialName("reserve-stock") data class ReserveStock(val orderId: String, val qty: Int) : Command
    @Serializable @SerialName("cancel-order") data class CancelOrder(val orderId: String) : Command
}

fun handle(c: Command) = when (c) {                 // exhaustive, no else branch
    is Command.ReserveStock -> stock.reserve(c.orderId, c.qty)
    is Command.CancelOrder -> stock.cancel(c.orderId)
}
